#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

#define FC_TYPE_MGMT 0x0u

#define MGMT_SUBTYPE_DISASSOC 0x0Au
#define MGMT_SUBTYPE_DEAUTH   0x0Cu

/* Frame Control (2 bytes) + Duration/ID (2) + Addr1 (6) = 10 bytes minimum
   needed to classify a management frame and read its destination address. */
#define MIN_MGMT_LEN 10u

bool block_frame(const uint8_t *f, size_t n)
{
    if (f == NULL || n < MIN_MGMT_LEN) {
        return false;
    }

    const uint8_t fc = f[0];
    const uint8_t type = (uint8_t)((fc >> 2) & 0x3u);
    const uint8_t subtype = (uint8_t)((fc >> 4) & 0xFu);

    if (type != FC_TYPE_MGMT) {
        return false;
    }

    return subtype == MGMT_SUBTYPE_DEAUTH || subtype == MGMT_SUBTYPE_DISASSOC;
}

