---- filter.c ----
#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

#define FC_TYPE_MGMT 0

#define SUBTYPE_DISASSOC 10
#define SUBTYPE_DEAUTH 12

/*
 * Drops management-frame deauthentication/disassociation frames, the payload of
 * a deauth/disassoc flood used to knock OT/ICS stations off their WLAN.
 */
bool block_frame(const uint8_t *f, size_t n)
{
    uint8_t fc, type, subtype;

    if (f == NULL || n < 2)
        return false;

    fc = f[0];
    type = (uint8_t)((fc >> 2) & 0x03);
    subtype = (uint8_t)((fc >> 4) & 0x0F);

    if (type != FC_TYPE_MGMT)
        return false;

    return subtype == SUBTYPE_DEAUTH || subtype == SUBTYPE_DISASSOC;
}

