import type { EventType, TimelineLine } from "./types";

export type AttackStatus =
  | "Devin processing"
  | "Devin fixing"
  | "Devin verifying"
  | "Devin deploying"
  | "Fix deployed";

export interface AttackRecord {
  id: number;
  ts: number;
  nodeId: string;
  name: string;
  packetCount: number;
  status: AttackStatus;
  events: TimelineLine[]; // this incident's own thread, oldest -> newest
}

export interface AttackPacket {
  id: string;
  nodeId: string;
  frameType: string;
  match: string;
}

const STATUS_BY_EVENT: Partial<Record<EventType, AttackStatus>> = {
  ANOMALY_DETECTED: "Devin processing",
  AGENT_ANALYZING: "Devin processing",
  FILTER_GENERATED: "Devin fixing",
  VERIFYING: "Devin verifying",
  VERIFY_FAILED: "Devin verifying",
  VERIFY_PASSED: "Devin verifying",
  OTA_DEPLOYING: "Devin deploying",
  DEPLOYED: "Fix deployed",
  FRAME_BLOCKED: "Fix deployed",
};

export function selectFrameFeed(timeline: TimelineLine[], limit: number): TimelineLine[] {
  // `timeline` is newest-first; show the most recent `limit` in chronological
  // order (oldest at top, newest at the bottom) so the defense loop reads top-down.
  return timeline.slice(0, Math.max(0, limit)).reverse();
}

function parsePacketCount(text: string): number {
  const match = text.match(/([\d,]+)\s+(?:attack\s+)?frames?/i);
  return match ? Number(match[1].replaceAll(",", "")) : 1;
}

function parseAttackClass(lines: TimelineLine[]): string | undefined {
  const generated = lines.find((line) => line.type === "FILTER_GENERATED");
  return generated?.text.match(/generated:\s*([a-z\d_ -]+)/i)?.[1]?.trim();
}

function formatAttackName(value?: string | null): string {
  if (!value) return "Frame flood";
  const words = value.replaceAll("_", " ").trim();
  return words.charAt(0).toUpperCase() + words.slice(1);
}

export function selectAttackHistory(timeline: TimelineLine[], activeAttack: string | null): AttackRecord[] {
  const anomalyIndexes = timeline.flatMap((line, index) => (line.type === "ANOMALY_DETECTED" ? [index] : []));

  return anomalyIndexes.map((index, attackIndex) => {
    const segmentStart = attackIndex === 0 ? 0 : anomalyIndexes[attackIndex - 1] + 1;
    const anomaly = timeline[index];
    const related = timeline
      .slice(segmentStart, index + 1)
      .filter((line) => line.node_id === anomaly.node_id);
    const status = related.map((line) => STATUS_BY_EVENT[line.type]).find(Boolean) ?? "Devin processing";
    const attackClass = parseAttackClass(related) ?? (attackIndex === 0 ? activeAttack : null);

    return {
      id: anomaly.id,
      ts: anomaly.ts,
      nodeId: anomaly.node_id ?? "system",
      name: formatAttackName(attackClass),
      packetCount: parsePacketCount(anomaly.text),
      status,
      events: related.slice().reverse(), // oldest -> newest for a readable thread
    };
  });
}

export function selectAttackPackets(attack: AttackRecord, limit = 6): AttackPacket[] {
  const count = Math.min(Math.max(0, limit), attack.packetCount);
  const frameType = /deauth/i.test(attack.name) ? "Deauthentication" : "Matched frame";

  return Array.from({ length: count }, (_, index) => ({
    id: `PKT-${String(attack.id).padStart(4, "0")}-${String(index + 1).padStart(3, "0")}`,
    nodeId: attack.nodeId,
    frameType,
    match: "Linked signature",
  }));
}

        )}
      </div>
    </aside>
  );
}

function attackId(attack: AttackRecord): string {
  return `ATK-${String(attack.id).padStart(4, "0")}`;
}

function AttackHistory({ timeline, activeAttack }: { timeline: TimelineLine[]; activeAttack: string | null }) {
  const [expandedId, setExpandedId] = useState<number | null>(null);
  const attacks = selectAttackHistory(timeline, activeAttack).slice(0, 6);

  return (
    <section className="attack-history" aria-labelledby="attack-history-heading">
      <div className="attack-history-heading">
        <div>
          <h2 id="attack-history-heading">Attack history</h2>
          <p>Detected incidents and Devin response state</p>
        </div>
        <span>{attacks.length} attacks</span>
      </div>

      <div className="attack-history-columns" aria-hidden="true">
        <span>Attack</span>
        <span>Router</span>
        <span>Packets</span>
        <span>Status</span>
        <span>Time</span>
        <span />
      </div>

      <div className="attack-history-list">
        {attacks.length === 0 ? (
          <div className="attack-history-empty">
            <strong>No attacks recorded</strong>
            <span>Waiting for an anomaly detection event.</span>
          </div>
        ) : (
          attacks.map((attack) => {
            const expanded = expandedId === attack.id;
            const panelId = `attack-${attack.id}-thread`;
            return (
              <article className="attack-history-item" data-expanded={expanded || undefined} key={attack.id}>
                <button
                  className="attack-history-toggle"
                  type="button"
                  aria-expanded={expanded}
                  aria-controls={panelId}
                  onClick={() => setExpandedId(expanded ? null : attack.id)}
                >
                  <span className="attack-identity">
                    <strong>{attack.name}</strong>
                    <small>{attackId(attack)}</small>
                  </span>
                  <span>{displayRouterName(attack.nodeId)}</span>
                  <strong className="attack-packet-count">{attack.packetCount}</strong>
                  <span className="attack-status">{attack.status}</span>
                  <time>{formatClock(attack.ts)}</time>
                  <span className="attack-toggle-label">{expanded ? "Hide thread" : "View thread"}</span>
                </button>

                {expanded && (
                  <div className="attack-thread" id={panelId}>
                    <div className="attack-thread-heading">
                      <strong>Devin response thread</strong>
                      <span>{attack.events.length} steps · {displayRouterName(attack.nodeId)}</span>
                    </div>
                    <ol className="attack-thread-list">
                      {attack.events.map((ev) => (
                        <li className="attack-thread-step" data-tone={ev.tone} key={ev.id}>
                          <time>{formatClock(ev.ts)}</time>
                          <span className="attack-thread-name">{EVENT_NAMES[ev.type]}</span>
                          <span className="attack-thread-text">{displayRouterName(ev.text)}</span>
                        </li>
                      ))}
                    </ol>
                  </div>
                )}
              </article>
            );
          })
        )}
      </div>
    </section>
  );
}

export default function App() {
  const { state } = useLive();
  const nodes = Object.values(state.nodes).sort((a, b) => a.node_id.localeCompare(b.node_id));

  return (
    <div className="dashboard-shell">

"""Fake 'Devin' agent — canned filters behind the real AgentIn->AgentOut contract.

Swapped for a real Devin/LLM call at integration (see ARCHITECTURE.md §5 step 2).
The orchestrator does not care which one it talks to.

To exercise the real fail->retry->pass loop, the first attempt over-blocks
(catches every management frame, so beacons get dropped -> FPR>0 -> oracle FAIL)
and the retry, once handed the failure log, narrows to deauth/disassoc only.
"""

from __future__ import annotations

from collections.abc import Callable
from pathlib import Path

from .models import AgentIn, AgentOut

StepFn = Callable[[str], None]

_GOOD_FILTER = (Path(__file__).resolve().parent.parent / "oracle/filters/deauth.c").read_text()

_OVERBROAD_FILTER = """\
#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

/* First guess: block ALL management frames. Too aggressive — drops beacons. */
bool block_frame(const uint8_t *f, size_t n) {
    if (n < 1) return false;
    uint8_t type = (f[0] >> 2) & 0x3;
    return type == 0x0;
}
"""


def call_agent(payload: AgentIn, on_step: StepFn | None = None) -> AgentOut:
    def step(msg: str) -> None:
        if on_step is not None:
            on_step(msg)

    retrying = bool(payload.failure_log or payload.prev_filter)
    if retrying:
        step("re-reading failure log; narrowing the filter")
        step("recompiled filter.c, re-ran harness: TPR=1.000 FPR=0.000")
        return AgentOut(
            attack_class="deauth_flood",
            confidence=0.94,
            filter_c_code=_GOOD_FILTER,
            explanation=(
                "Narrowed to 802.11 mgmt subtypes 0xC (deauth) and 0xA (disassoc); "
                "beacons and data frames now pass."
            ),
            iterations=2,
            compiled=True,
            self_tpr=1.0,
            self_fpr=0.0,
        )
    step("wrote filter.c, compiled with gcc -Wall")
    step("ran harness: over-blocks beacons (FPR>0) — needs a fix")
    return AgentOut(
        attack_class="deauth_flood",
        confidence=0.71,
        filter_c_code=_OVERBROAD_FILTER,
        explanation="Initial guess: high volume of management frames — block all mgmt.",
        iterations=1,
        compiled=True,
        self_tpr=1.0,
        self_fpr=0.5,
    )

